import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import path from "node:path";
import { projectRoot } from "./env-files.ts";

const MARKER =
  "Generated by npm run agents:sync from .agents. Edit the source, then run the command.";
const IGNORE_MARKER =
  "Generated by npm run agents:sync from .agents/ignore. Edit that file, then run the command.";
const CLAUDE_SCHEMA = "https://json.schemastore.org/claude-code-settings.json";

type Trigger = "always_on" | "glob";

type Rule = {
  name: string;
  description: string;
  trigger: Trigger;
  globs: string[];
  body: string;
};

type IgnoreList = {
  patterns: string[];
  exceptions: string[];
};

type Manifest = {
  files: string[];
  claudeDenies: string[];
};

const root = projectRoot();
const sourceRulesDir = path.join(root, ".agents", "rules");
const sourceSkillsDir = path.join(root, ".agents", "skills");
const ignoreSource = path.join(root, ".agents", "ignore");
const manifestPath = path.join(root, ".agents", "sync-manifest.json");
const skillDestinations = [
  ".cursor/skills",
  ".claude/skills",
  ".codex/skills",
  ".github/skills",
];

function relativeToRoot(file: string): string {
  return path.relative(root, file).split(path.sep).join("/");
}

function insideRoot(file: string): string {
  const resolved = path.resolve(file);
  const relative = path.relative(root, resolved);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`Refusing to touch a path outside the project: ${file}`);
  }
  return resolved;
}

function readText(file: string): string {
  return readFileSync(file, "utf8").replace(/\r\n/g, "\n");
}

function writeIfChanged(file: string, contents: string): void {
  const next = contents.endsWith("\n") ? contents : `${contents}\n`;
  writeBytesIfChanged(file, Buffer.from(next, "utf8"));
}

function writeBytesIfChanged(file: string, contents: Buffer): void {
  const resolved = insideRoot(file);
  const label = relativeToRoot(resolved);
  mkdirSync(path.dirname(resolved), { recursive: true });
  if (existsSync(resolved) && readFileSync(resolved).equals(contents)) {
    console.log(`No changes for ${label}`);
    return;
  }
  const created = !existsSync(resolved);
  writeFileSync(resolved, contents);
  console.log(`${created ? "Created" : "Updated"} ${label}`);
}

function parseRule(file: string): Rule {
  const text = readText(file);
  const match = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(text);
  if (!match) {
    throw new Error(`${relativeToRoot(file)} needs frontmatter wrapped in ---`);
  }
  const frontmatter = match[1] ?? "";
  const body = (match[2] ?? "").trim();
  if (!body) throw new Error(`${relativeToRoot(file)} has an empty body`);

  let description = "";
  let trigger: Trigger | undefined;
  const globs: string[] = [];
  let readingGlobs = false;
  for (const line of frontmatter.split("\n")) {
    if (line.trim() === "") continue;
    if (readingGlobs && /^\s+-\s+/.test(line)) {
      globs.push(line.replace(/^\s+-\s+/, "").trim());
      continue;
    }
    readingGlobs = false;
    const field = /^([A-Za-z]+):\s*(.*)$/.exec(line);
    if (!field)
      throw new Error(`${relativeToRoot(file)} has an unreadable line: ${line}`);
    const key = field[1];
    const value = (field[2] ?? "").trim();
    if (key === "description") description = value.replace(/^["']|["']$/g, "");
    else if (key === "trigger") {
      if (value !== "always_on" && value !== "glob") {
        throw new Error(`${relativeToRoot(file)} trigger must be always_on or glob`);
      }
      trigger = value;
    } else if (key === "globs") {
      if (value !== "")
        throw new Error(`${relativeToRoot(file)} lists globs on following lines`);
      readingGlobs = true;
    } else {
      throw new Error(
        `${relativeToRoot(file)} has an unknown frontmatter field: ${key}`,
      );
    }
  }
  if (!description) throw new Error(`${relativeToRoot(file)} needs a description`);
  if (!trigger) throw new Error(`${relativeToRoot(file)} needs a trigger`);
  if (trigger === "always_on" && globs.length > 0) {
    throw new Error(`${relativeToRoot(file)} is always_on and cannot list globs`);
  }
  if (trigger === "glob" && globs.length === 0) {
    throw new Error(`${relativeToRoot(file)} needs at least one glob`);
  }
  return {
    name: path.basename(file, ".md"),
    description,
    trigger,
    globs,
    body,
  };
}

function loadRules(): Rule[] {
  if (!existsSync(sourceRulesDir)) throw new Error("Missing .agents/rules");
  return readdirSync(sourceRulesDir)
    .filter((name) => name.endsWith(".md"))
    .sort()
    .map((name) => parseRule(path.join(sourceRulesDir, name)));
}

function walkFiles(dir: string, relative = ""): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === "node_modules" || entry.name === ".git") continue;
    const rel = relative ? `${relative}/${entry.name}` : entry.name;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) out.push(...walkFiles(full, rel));
    else if (entry.isFile()) out.push(rel);
  }
  return out;
}

function loadSkillFiles(): { relative: string; source: string }[] {
  if (!existsSync(sourceSkillsDir)) return [];
  const files: { relative: string; source: string }[] = [];
  for (const entry of readdirSync(sourceSkillsDir, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const skillRoot = path.join(sourceSkillsDir, entry.name);
    if (!existsSync(path.join(skillRoot, "SKILL.md"))) {
      console.log(`Skipped .agents/skills/${entry.name} because it has no SKILL.md`);
      continue;
    }
    for (const relative of walkFiles(skillRoot).sort()) {
      files.push({
        relative: `${entry.name}/${relative}`,
        source: path.join(skillRoot, ...relative.split("/")),
      });
    }
  }
  return files.sort((left, right) => left.relative.localeCompare(right.relative));
}

function isOwnSkillCopy(relative: string): boolean {
  return skillDestinations.some(
    (destination) => relative === destination || relative.startsWith(`${destination}/`),
  );
}

function pruneEmptyDirs(dir: string): void {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) pruneEmptyDirs(path.join(dir, entry.name));
  }
  if (readdirSync(dir).length === 0) rmSync(dir);
}

function loadIgnore(): IgnoreList {
  if (!existsSync(ignoreSource)) throw new Error("Missing .agents/ignore");
  const patterns: string[] = [];
  const exceptions: string[] = [];
  for (const line of readText(ignoreSource).split("\n")) {
    const trimmed = line.trim();
    if (trimmed === "" || trimmed.startsWith("#")) continue;
    if (trimmed.startsWith("!")) exceptions.push(trimmed.slice(1).trim());
    else patterns.push(trimmed);
  }
  return { patterns, exceptions };
}

function globToRegExp(pattern: string): RegExp {
  const directory = pattern.endsWith("/");
  const bare = directory ? pattern.slice(0, -1) : pattern;
  const escaped = bare
    .replace(/[.+^${}()|[\]\\]/g, "\\$&")
    .replace(/\*\*/g, "@@DOUBLE@@");
  const starred = escaped.replace(/\*/g, "[^/]*").replace(/@@DOUBLE@@/g, ".*");
  const body = directory ? `${starred}(?:/.*)?` : starred;
  return new RegExp(`^(?:.*/)?${body}$`);
}

function patternHidesException(pattern: string, exception: string): boolean {
  return globToRegExp(pattern).test(exception);
}

function claudeDenies(ignore: IgnoreList): string[] {
  const denies: string[] = [];
  for (const pattern of ignore.patterns) {
    const hidesExample = ignore.exceptions.some((exception) =>
      patternHidesException(pattern, exception),
    );
    if (hidesExample) continue;
    let target = pattern;
    const directory = target.endsWith("/");
    if (directory) target = target.slice(0, -1);
    if (target.startsWith("./")) target = target.slice(2);
    if (!target.startsWith("**") && !target.includes("/")) target = `**/${target}`;
    if (directory) target = `${target}/**`;
    denies.push(`Read(${target})`);
  }
  return denies;
}

function yamlQuote(value: string): string {
  if (/^[A-Za-z0-9][A-Za-z0-9 .,'/-]*$/.test(value)) return value;
  return JSON.stringify(value);
}

function banner(): string {
  return `<!-- ${MARKER} -->`;
}

function ignoreBanner(): string {
  return `# ${IGNORE_MARKER}`;
}

function appliesTo(rule: Rule): string {
  return rule.globs.map((glob) => `\`${glob}\``).join(" and ");
}

function closedPaths(ignore: IgnoreList): string {
  const lines = [
    "## Paths to leave closed",
    "",
    "Do not open, quote, or modify these paths.",
    "",
    ...ignore.patterns.map((pattern) => `- \`${pattern}\``),
  ];
  if (ignore.exceptions.length > 0) {
    lines.push("", "These example files may be read:", "");
    for (const pattern of ignore.exceptions) lines.push(`- \`${pattern}\``);
  }
  return lines.join("\n");
}

function combinedInstructions(rules: Rule[], ignore: IgnoreList): string {
  const parts = [banner()];
  for (const rule of rules.filter((item) => item.trigger === "always_on")) {
    parts.push("", rule.body);
  }
  const scoped = rules.filter((item) => item.trigger === "glob");
  if (scoped.length > 0) {
    parts.push("", "## Scoped rules");
    for (const rule of scoped) {
      parts.push(
        "",
        `### ${rule.description}`,
        "",
        `Applies to ${appliesTo(rule)}.`,
        "",
        rule.body,
      );
    }
  }
  parts.push("", closedPaths(ignore), "");
  return parts.join("\n");
}

function cursorRule(rule: Rule): string {
  const lines = ["---", `description: ${yamlQuote(rule.description)}`];
  if (rule.trigger === "always_on") lines.push("alwaysApply: true");
  else {
    lines.push(`globs: ${rule.globs.join(",")}`, "alwaysApply: false");
  }
  lines.push("---", "", banner(), "", rule.body, "");
  return lines.join("\n");
}

function claudeRule(rule: Rule): string {
  const paths = rule.globs.map((glob) => `  - "${glob}"`).join("\n");
  return ["---", "paths:", paths, "---", "", banner(), "", rule.body, ""].join("\n");
}

function copilotInstruction(rule: Rule): string {
  return [
    "---",
    `applyTo: "${rule.globs.join(",")}"`,
    "---",
    "",
    banner(),
    "",
    rule.body,
    "",
  ].join("\n");
}

function gitignoreCopy(source: string): string {
  const body = readText(source)
    .replace(/^#.*\n/gm, "")
    .trim();
  return `${ignoreBanner()}\n\n${body}\n`;
}

function readManifest(): Manifest {
  if (!existsSync(manifestPath)) return { files: [], claudeDenies: [] };
  const parsed: unknown = JSON.parse(readText(manifestPath));
  if (!parsed || typeof parsed !== "object") return { files: [], claudeDenies: [] };
  const record = parsed as { files?: unknown; claudeDenies?: unknown };
  return {
    files: Array.isArray(record.files)
      ? record.files.filter((file): file is string => typeof file === "string")
      : [],
    claudeDenies: Array.isArray(record.claudeDenies)
      ? record.claudeDenies.filter(
          (entry): entry is string => typeof entry === "string",
        )
      : [],
  };
}

function writeClaudeSettings(denies: string[], previousDenies: string[]): void {
  const file = path.join(root, ".claude", "settings.json");
  const existing: Record<string, unknown> = existsSync(file)
    ? (JSON.parse(readText(file)) as Record<string, unknown>)
    : {};
  const permissions =
    existing.permissions && typeof existing.permissions === "object"
      ? { ...(existing.permissions as Record<string, unknown>) }
      : {};
  const current = Array.isArray(permissions.deny)
    ? permissions.deny.filter((entry): entry is string => typeof entry === "string")
    : [];
  const previous = new Set(previousDenies);
  const nextDeny = new Set(denies);
  const kept = current.filter((entry) => !previous.has(entry) && !nextDeny.has(entry));
  permissions.deny = [...kept, ...denies];
  const next = {
    $schema: CLAUDE_SCHEMA,
    ...existing,
    permissions,
  };
  writeIfChanged(file, `${JSON.stringify(next, null, 2)}\n`);
}

function removeStale(previous: string[], next: Set<string>): void {
  for (const relative of previous) {
    if (next.has(relative)) continue;
    const resolved = insideRoot(path.join(root, relative));
    if (!existsSync(resolved)) continue;
    const generatedCopy = isOwnSkillCopy(relative);
    const text = generatedCopy ? "" : readText(resolved);
    if (!generatedCopy && !text.includes(MARKER) && !text.includes(IGNORE_MARKER)) {
      console.log(`Left ${relative} in place because this command did not generate it`);
      continue;
    }
    rmSync(resolved);
    console.log(`Removed ${relative}`);
  }
}

const rules = loadRules();
const ignore = loadIgnore();
const previous = readManifest();
const combined = combinedInstructions(rules, ignore);
const denies = claudeDenies(ignore);
const outputs = new Set<string>();

function track(file: string): string {
  outputs.add(relativeToRoot(file));
  return file;
}

writeIfChanged(track(path.join(root, "AGENTS.md")), combined);
writeIfChanged(track(path.join(root, "GEMINI.md")), combined);
writeIfChanged(track(path.join(root, "CLAUDE.md")), `${banner()}\n\n@AGENTS.md\n`);

for (const rule of rules) {
  writeIfChanged(
    track(path.join(root, ".cursor", "rules", `${rule.name}.mdc`)),
    cursorRule(rule),
  );
  if (rule.trigger === "glob") {
    writeIfChanged(
      track(path.join(root, ".claude", "rules", `${rule.name}.md`)),
      claudeRule(rule),
    );
    writeIfChanged(
      track(path.join(root, ".github", "instructions", `${rule.name}.instructions.md`)),
      copilotInstruction(rule),
    );
  }
}

const copilot = [banner()];
for (const rule of rules.filter((item) => item.trigger === "always_on")) {
  copilot.push("", rule.body);
}
copilot.push("", closedPaths(ignore), "");
writeIfChanged(
  track(path.join(root, ".github", "copilot-instructions.md")),
  copilot.join("\n"),
);
writeIfChanged(track(path.join(root, ".cursorignore")), gitignoreCopy(ignoreSource));
writeIfChanged(track(path.join(root, ".geminiignore")), gitignoreCopy(ignoreSource));

for (const skill of loadSkillFiles()) {
  const bytes = readFileSync(skill.source);
  for (const destination of skillDestinations) {
    const file = path.join(root, destination, skill.relative);
    track(file);
    writeBytesIfChanged(file, bytes);
  }
}

const settingsPath = path.join(root, ".claude", "settings.json");
outputs.add(relativeToRoot(settingsPath));
writeClaudeSettings(denies, previous.claudeDenies);

removeStale(previous.files, outputs);
for (const destination of skillDestinations) {
  pruneEmptyDirs(path.join(root, destination));
}

const manifest: Manifest = {
  files: [...outputs].sort(),
  claudeDenies: denies,
};
writeIfChanged(manifestPath, `${JSON.stringify(manifest, null, 2)}\n`);
